function parseRemoteResponse(
	data: unknown
): { ok: true; response: RemoteAskResponse } | { message: string; ok: false } {
	if (!isPlainObject(data)) {
		return { ok: false, message: "Submit response must be an object." };
	}
	if (data.kind === "cancel") {
		return { ok: true, response: { kind: "cancel" } };
