	if (data.kind === "answer") {
		return {
			ok: true,
			response: {
				kind: "answer",
				answers: data.answers as Record<string, RemoteAskAnswer>,
				mode: data.mode as "submit" | "elaborate" | undefined,
			},
		};
	}
	return {
		ok: false,
		message: 'Submit response kind must be "answer" or "cancel".',
	};
}

